files.agents/models.json:
{
  "_comment": [
    "Per-agent model and thinking level, per harness. This file is the single source:",
    "`scripts/sync-agent-models.py` writes these values into every agent's frontmatter,",
    "and `--check` fails when a file has drifted. bootstrap-plugins.sh syncs before it",
    "installs, so editing here and re-running the installer is the whole workflow.",
    "",
    "Fields per harness, and where each one actually takes effect — verified against",
    "each CLI, not assumed. The three harnesses differ in what they can scope per agent:",
    "",
    "  claude -> model: opus | sonnet | haiku | inherit   effort: low|medium|high|xhigh",
    "            Both are real agent frontmatter. Fully per-agent.",
    "",
    "  codex  -> model: <model id>                        effort: low|medium|high|xhigh|max",
    "            Codex has no plugin-manifest `agents` key, so the staged plugin generates",
    "            a routing contract that requires every Nova spawn_agent dispatch to",
    "            pass this model and reasoning_effort explicitly. bootstrap-plugins.sh",
    "            rebuilds and reinstalls that contract whenever this file changes. The",
    "            installer also writes $CODEX_HOME/nova-<agent>.config.toml profiles",
    "            for manually launching one role with `codex --profile nova-<agent>`.",
    "            Read-only isolation is owned by the launching process: use `codex exec",
    "            -s read-only` or a nova-<agent> profile, and re-verify this per release.",
    "",
    "  agy    -> model: gemini-3.8-flash | pro | flash | inherit (no per-agent effort)",
    "            `model` is real agent frontmatter, defaulting to `inherit` (the",
    "            parent's model). Antigravity does have reasoning effort, but only",
    "            session-wide, via the `/effort` command or the `--effort` launch flag —",
    "            there is no frontmatter key for it, so an effort set here would be a lie.",
    "",
    "An agent inherits `defaults` for any field it does not override."
  ],
  "defaults": {
    "claude": {
      "model": "claude-sonnet-5",
      "effort": "medium"
    },
    "codex": {
      "model": "gpt-6-astra",
      "effort": "medium"
    },
    "agy": {
      "model": "gemini-3.8-flash"
    }
  },
  "agents": {
    "planner": {
      "_why": "Investigation and decomposition set the ceiling for the whole milestone; a weak plan costs every wave after it.",
      "claude": {
        "model": "claude-opus-5",
        "effort": "xhigh"
      },
      "codex": {
        "model": "gpt-6-astra",
        "effort": "high"
      },
      "agy": {
        "model": "gemini-3.8-flash"
      }
    },
    "specifier": {
      "_why": "Writes the Definition of Done nobody downstream can weaken. A lazy acceptance test here is invisible and permanent.",
      "claude": {
        "model": "claude-opus-5",
        "effort": "high"
      },
      "codex": {
        "model": "gpt-6-astra",
        "effort": "high"
      },
      "agy": {
        "model": "gemini-3.8-flash"
      }
    },
    "builder": {
      "_why": "Implements against a fixed target, with the guard and independent review behind it.",
      "claude": {
        "model": "claude-fable-5-1",
        "effort": "high",
        "mode": "de-prescribed"
      },
      "codex": {
        "model": "gpt-6-astra",
        "effort": "high"
      },
      "agy": {
        "model": "gemini-3.8-flash"
      }
    },
    "reviewer": {
      "_why": "One lens over one diff, structured output. Narrow and repeated, so it runs cheap and often.",
      "claude": {
        "model": "claude-sonnet-5",
        "effort": "medium"
      },
      "codex": {
        "model": "gpt-6-astra",
        "effort": "medium"
      },
      "agy": {
        "model": "gemini-3.8-flash"
      }
    },
    "integrator": {
      "_why": "Runs commands and reports evidence. The judgment is bisecting a combined failure, not writing code.",
      "claude": {
        "model": "claude-sonnet-5",
        "effort": "medium"
      },
      "codex": {
        "model": "gpt-6-astra",
        "effort": "medium"
      },
      "agy": {
        "model": "gemini-3.8-flash"
      }
    },
    "researcher": {
      "_why": "Gathers evidence for one area; the calling planner synthesizes it.",
      "claude": {
        "model": "claude-sonnet-5",
        "effort": "low"
      },
      "codex": {
        "model": "gpt-6-astra",
        "effort": "low"
      },
      "agy": {
        "model": "gemini-3.8-flash"
      }
    },
    "documenter": {
      "_why": "Prose against a fixed standard, over code someone else already settled.",
      "claude": {
        "model": "claude-sonnet-5",
        "effort": "medium"
      },
      "codex": {
        "model": "gpt-6-astra",
        "effort": "medium"
      },
      "agy": {
        "model": "gemini-3.8-flash"
      }
    },
    "deployer": {
      "_why": "Outward-facing and hard to reverse; a wrong call costs more than the tokens saved.",
      "claude": {
        "model": "claude-opus-5",
        "effort": "high"
      },
      "codex": {
        "model": "gpt-6-astra",
        "effort": "high"
      },
      "agy": {
        "model": "gemini-3.8-flash"
      }
    },
    "debugger": {
      "_why": "Hypothesis forming and refutation is the hardest reasoning in the fleet; a wrong root cause sends a builder to fix the wrong thing.",
      "claude": {
        "model": "claude-fable-5-1",
        "effort": "high",
        "mode": "de-prescribed"
      },
      "codex": {
        "model": "gpt-6-astra",
        "effort": "high"
      },
      "agy": {
        "model": "gemini-3.8-flash"
      }
    },
    "profiler": {
      "_why": "Disciplined measurement, not deep reasoning. The rigour is in the method, which this file cannot buy with a bigger model.",
      "claude": {
        "model": "claude-sonnet-5",
        "effort": "medium"
      },
      "codex": {
        "model": "gpt-6-astra",
        "effort": "medium"
      },
      "agy": {
        "model": "gemini-3.8-flash"
      }
    }
  },
  "model_guides": {
    "claude": {
      "opus": "claude-opus-5",
      "sonnet": "claude-sonnet-5",
      "claude-opus-5": "claude-opus-5",
      "claude-sonnet-5": "claude-sonnet-5",
      "claude-fable-5-1": "claude-fable-5-1"
    },
    "agy": {
      "gemini-3.8-flash": "docs/models/gemini-3.8-flash/prompting.md"
    }
  }
}

files.cmd/tdd-guard/main.go:
package main

import (
	"os"

	"github.com/anvil008/nova/guard"
)

func main() {
	os.Exit(guard.Run(guard.Options{Stdin: os.Stdin, Stdout: os.Stdout, Stderr: os.Stderr}, os.Args[1:]))
}

