package guard

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func (h *harness) review() {
	h.t.Helper()
	findings := filepath.Join(h.t.TempDir(), "findings.txt")
	if err := os.WriteFile(findings, []byte("Read the current diff and checked the behavior.\n"), 0o600); err != nil {
		h.t.Fatal(err)
	}
	if code, _, stderr := h.run("diff-review", "record", "--findings", findings); code != 0 {
		h.t.Fatalf("review: %s", stderr)
	}
}

func TestGreenCannotBeRefreshedByReviewingARegression(t *testing.T) {
	h := newHarness(t)
	h.seal()
	h.verify()
	h.review()
	if !h.status().Ready {
		t.Fatal("initial passing implementation was not ready")
	}
	h.write("pkg/thing.go", "package pkg\n// regression after GREEN\n")
	h.review()
	status := h.status()
	if status.Ready || !status.GreenStale || status.DiffStale {
		t.Fatalf("a fresh review revived stale GREEN: %+v", status)
	}
	if code, _, stderr := h.stop(); code != 2 || !strings.Contains(stderr, "green evidence is stale") {
		t.Fatalf("Stop accepted the regression: %d %s", code, stderr)
	}
	h.verify()
	if !h.status().Ready {
		t.Fatal("reverification of the unchanged reviewed tree should recover readiness")
	}
}

func TestFailedVerificationDiscardsPreviousGreenEvenOnTheSameTree(t *testing.T) {
	h := newHarness(t)
	argv := []string{"sh", "-c", `test "$NOVA_VERIFY_RESULT" = pass`}
	t.Setenv("NOVA_VERIFY_RESULT", "fail")
	if code, _, stderr := h.run(append([]string{"seal", "--tests", "**/*_test.go", "--red-command"}, argv...)...); code != 0 {
		t.Fatal(stderr)
	}
	t.Setenv("NOVA_VERIFY_RESULT", "pass")
	if code, _, stderr := h.run(append([]string{"verify", "--green-command"}, argv...)...); code != 0 {
		t.Fatal(stderr)
	}
	h.review()
	t.Setenv("NOVA_VERIFY_RESULT", "fail")
	if code, _, _ := h.run(append([]string{"verify", "--green-command"}, argv...)...); code == 0 {
		t.Fatal("failing rerun was accepted")
	}
	if status := h.status(); status.Ready || status.Green != nil {
		t.Fatalf("failed attempt retained an earlier success: %+v", status)
	}
	if code, _, _ := h.stop(); code != 2 {
		t.Fatal("failed verification inherited the specifier Stop relaxation")
	}
}

func TestFailedFirstVerificationEndsSpecifierStopRelaxation(t *testing.T) {
	h := newHarness(t)
	h.seal()
	if code, _, stderr := h.run("handoff", "--to", "builder"); code != 0 {
		t.Fatal(stderr)
	}
	if code, _, _ := h.stop(); code != 0 {
		t.Fatal("specifier cannot hand off an unchanged sealed tree")
	}
	if code, _, _ := h.run(append([]string{"verify", "--green-command"}, boundArgv...)...); code == 0 {
		t.Fatal("expected first verification to fail")
	}
	if code, _, _ := h.stop(); code != 2 {
		t.Fatal("failed verification inherited the specifier Stop relaxation")
	}
}

func TestVerificationRejectsSourceChangesDuringTheCommand(t *testing.T) {
	h := newHarness(t)
	argv := []string{"sh", "-c", "test -f .green || exit 1; printf changed > pkg/thing.go"}
	if code, _, stderr := h.run(append([]string{"seal", "--tests", "**/*_test.go", "--red-command"}, argv...)...); code != 0 {
		t.Fatal(stderr)
	}
	h.write(".green", "")
	if code, _, stderr := h.run(append([]string{"verify", "--green-command"}, argv...)...); code == 0 || !strings.Contains(stderr, "implementation changed") {
		t.Fatalf("mutating command was accepted: %d %s", code, stderr)
	}
	if h.status().Green != nil {
		t.Fatal("mutating command left GREEN")
	}
}

func TestLegacyGreenAndMovedBaseRequireReverification(t *testing.T) {
	h := newHarness(t)
	h.seal()
	h.verify()
	h.review()
	legacy := h.greenRecord()
	delete(legacy, "base")
	if err := writeJSON(filepath.Join(h.stateDirectory(), greenFileName), legacy); err != nil {
		t.Fatal(err)
	}
	if status := h.status(); status.Ready || !status.GreenStale {
		t.Fatal("unbound legacy GREEN was trusted")
	}
	h.verify()
	h.commit("same content, different base")
	if status := h.status(); status.Ready || !status.GreenStale || !status.DiffStale {
		t.Fatal("moved base retained old evidence")
	}
}

files.guard/guard.go:
// Package guard implements tdd-guard, the harness-neutral test-seal and
// diff-review gate. It records either a RED baseline for behaviour changes or
// a GREEN baseline for refactors, refuses edits to sealed tests, and refuses to
// let an agent stop until a passing run and a real diff review exist for the
// change actually on disk.
package guard

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/anvil008/nova/controlplane"
)

const (
	// APIVersion identifies the machine-readable `status` contract.
	APIVersion = "anvil.guard/v1"
	// StateEnv overrides the base directory holding per-repository state.
	StateEnv = "ANVIL_GUARD_STATE"
	// ConfigPath is the repository-relative test-glob override.
	ConfigPath = ".anvil/guard.json"
	// AstGrepEnv overrides the ast-grep binary the arch-check resolves. It exists
	// so the structural verifier can be pinned or, in tests, replaced by a
	// stand-in; when unset the check resolves the default `ast-grep` on PATH.
	AstGrepEnv = "ANVIL_GUARD_ASTGREP"

	sealFileName       = "seal.json"
	greenFileName      = "green.json"
	diffReviewFileName = "diff-review.json"
	archReviewFileName = "arch-review.json"
	handoffFileName    = "handoff.json"
)

// DefaultTestPatterns is the fleet-wide test surface. A repository narrows or
// widens it through ConfigPath rather than through a per-invocation flag.
var DefaultTestPatterns = []string{
	"**/*_test.go", "**/*.spec.*", "**/*.test.*", "**/test_*.py", "**/tests/**", "**/testdata/**",
}

// TestDigest pins one sealed test file to its content at seal time.
type TestDigest struct {
	Path   string `json:"path"`
	Digest string `json:"digest"`
}

// Base pins the revision and working-tree state a seal or review was taken on.
type Base struct {
	HeadCommit string `json:"headCommit"`
	TreeDigest string `json:"treeDigest"`
}

// Amendment is the explicit, recorded permission to change a sealed test.
type Amendment struct {
	At     string       `json:"at"`
	Reason string       `json:"reason"`
	Before []TestDigest `json:"before"`
	After  []TestDigest `json:"after"`
}

// BoundArgv is the command the seal binds verification to. Only the same argv
// can later prove GREEN; otherwise `seal --red-command false` followed by
// `verify --green-command true` is a complete TDD cycle on paper.
type BoundArgv struct {
	Argv   []string `json:"argv"`
	Digest string   `json:"digest"`
}

// SealKind identifies which pre-implementation result made a seal valid.
type SealKind string

const (
	SealKindRed      SealKind = "red"
	SealKindBaseline SealKind = "baseline"
)

// Seal is the test baseline: the tests that must not move plus proof of the
// pre-implementation result required by Kind. Red retains its historical JSON
// name for compatibility; on a baseline seal it holds the successful baseline
// command evidence.
type Seal struct {
	Kind       SealKind                     `json:"kind"`
	SealedAt   string                       `json:"sealedAt"`
	Base       Base                         `json:"base"`
	Tests      []TestDigest                 `json:"tests"`
	Red        controlplane.CommandEvidence `json:"red"`
	Amendments []Amendment                  `json:"amendments"`
	// BoundArgv is absent from seals written before the binding existed; those
	// bind to Red.ArgvDigest, which every seal has always recorded.
	BoundArgv *BoundArgv `json:"boundArgv,omitempty"`
}

// kind treats seals written before the kind field existed as RED seals.
func (s *Seal) kind() SealKind {
	if s.Kind == "" {
		return SealKindRed
	}
	return s.Kind
}

// boundArgv returns the binding in force, synthesizing one for a legacy seal.
func (s *Seal) boundArgv() BoundArgv {
	if s.BoundArgv != nil {
		return *s.BoundArgv
	}
	return BoundArgv{Digest: s.Red.ArgvDigest}
}

// Green is the passing run recorded at verify time. It carries the full command
// evidence plus an optional test-strength signal. CoveragePercent is advisory:
// it is captured when `verify --coverage-command` is given and the tool emits a
// parseable percentage, and it never gates verification.
type Green struct {
	controlplane.CommandEvidence
	// Base binds the passing command to the implementation it actually tested.
	// Legacy records without this field must be verified again.
	Base            Base     `json:"base"`
	CoveragePercent *float64 `json:"coveragePercent,omitempty"`
}

// DiffReview records that the real `git diff HEAD` was read, not summarized.
// Command is the full evidence of that read; CommandID is the same identifier
// hoisted out so a reader does not have to reach into the evidence for it.
type DiffReview struct {
	ReviewedAt string                       `json:"reviewedAt"`
	CommandID  string                       `json:"commandId"`
	Command    controlplane.CommandEvidence `json:"command"`
	DiffDigest string                       `json:"diffDigest"`
	Base       Base                         `json:"base"`
	Findings   []string                     `json:"findings"`
}

// ArchAssertion is one structural design rule the arch-check evaluates with
// ast-grep: which module must call or import what, which boundary must hold.
// Expect is "present" (at least one match required) or "absent" (no match
// allowed); PathGlob narrows the files searched to a `**`-aware glob.
type ArchAssertion struct {
	ID          string `json:"id"`
	Description string `json:"description"`
	Pattern     string `json:"astGrepPattern"`
	Expect      string `json:"expect"`
	PathGlob    string `json:"pathGlob,omitempty"`
}

// ArchAssertionResult records how one assertion fared: the match count ast-grep
// reported and whether that satisfied the expectation.
type ArchAssertionResult struct {
	ArchAssertion
	MatchCount int  `json:"matchCount"`
	Passed     bool `json:"passed"`
}

// ArchReview is the executable architecture-conformance record: the structural
// assertions checked with ast-grep and whether each held. When ast-grep is not
// installed the review is Verified=false -- unverified, never passed -- mirroring
// the missing-verifier convention that a tool that never ran proves nothing, so
// an unverified review carries no command evidence and is not a citeable record.
type ArchReview struct {
	ReviewedAt string                        `json:"reviewedAt"`
	Verified   bool                          `json:"verified"`
	Passed     bool                          `json:"passed"`
	CommandID  string                        `json:"commandId,omitempty"`
	Command    *controlplane.CommandEvidence `json:"command,omitempty"`
	Results    []ArchAssertionResult         `json:"results"`
	Digest     string                        `json:"digest"`
	Base       Base                          `json:"base"`
}

// Handoff records that the agent which sealed the tests finished its part and
// owes the implementation to a different agent. It exists because a specifier
// legitimately stops with a seal and no GREEN: without this marker the Stop gate
// -- which is written for an implementer -- would deadlock it.
//
// A handoff relaxes the Stop gate only. It never satisfies the merge gate: an
// orchestrator reads Ready, which still requires GREEN and a fresh diff review.
type Handoff struct {
	HandedOffAt string `json:"handedOffAt"`
	To          string `json:"to"`
	// Base pins the working tree as it was handed over. The Stop relaxation
	// covers *that* state and nothing after it: once the next agent changes a
	// byte, it owes GREEN like any implementer, so a builder cannot coast to a
	// clean stop on the specifier's handoff.
	Base Base `json:"base"`
}

// Status is the machine-readable state the orchestrator reconciles.
type Status struct {
	APIVersion   string      `json:"apiVersion"`
	Repository   string      `json:"repository"`
	StateDir     string      `json:"stateDir"`
	Sealed       bool        `json:"sealed"`
	SealKind     SealKind    `json:"sealKind,omitempty"`
	Seal         *Seal       `json:"seal,omitempty"`
	BoundArgv    *BoundArgv  `json:"boundArgv,omitempty"`
	Green        *Green      `json:"green,omitempty"`
	DiffReview   *DiffReview `json:"diffReview,omitempty"`
	ArchReview   *ArchReview `json:"archReview,omitempty"`
	Handoff      *Handoff    `json:"handoff,omitempty"`
	ChangedTests []string    `json:"changedTests"`
	GreenStale   bool        `json:"greenStale"`
	DiffStale    bool        `json:"diffStale"`
	ArchStale    bool        `json:"archStale"`
	Ready        bool        `json:"ready"`
	// Records is the stable list of runs tdd-guard itself performed. It is
	// what the control plane resolves an agent-cited commandId against.
	Records []controlplane.GuardRecord `json:"records"`
}

// Snapshot reads one repository's guard-produced records without running git
// or touching the repository. The run-plane supervisor calls it directly after
// a foreign child exits; it returns nil when the repository was never sealed,
// because then there is nothing to resolve a cited commandId against.
//
// Note that this is resolution, not a trust boundary: the state directory is
// writable by the same OS user, so a deliberate forgery of these records is out
// of scope by design and is what the LXC 135 holdout measures.
func Snapshot(repositoryRoot string) (*controlplane.GuardSnapshot, error) {
	resolved := filepath.Clean(repositoryRoot)
	if evaluated, err := filepath.EvalSymlinks(resolved); err == nil {
		resolved = evaluated
	}
	loaded, err := loadRepositoryState(resolved)
	if err != nil {
		return nil, err
	}
	if loaded.seal == nil {
		return nil, nil
	}
	return &controlplane.GuardSnapshot{
		APIVersion: controlplane.GuardSnapshotAPIVersion,
		Repository: loaded.repository,
		Records:    loaded.records(),
	}, nil
}

// stateBaseDirectory resolves the directory holding every per-repository state
// directory and the per-session touch logs.
func stateBaseDirectory() (string, error) {
	base := strings.TrimSpace(os.Getenv(StateEnv))
	if base == "" {
		home, err := os.UserHomeDir()
		if err != nil {
			return "", fmt.Errorf("resolve home for guard state: %w", err)
		}
		base = filepath.Join(home, ".local", "state", "tdd-guard")
	}
	if !filepath.IsAbs(base) {
		return "", fmt.Errorf("guard state directory %q must be absolute", base)
	}
	return filepath.Clean(base), nil
}

// StateDirectory resolves the per-repository state directory. The repository
// path is hashed so unrelated checkouts of the same project stay separate.
func StateDirectory(repositoryRoot string) (string, error) {
	base, err := stateBaseDirectory()
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256([]byte(filepath.Clean(repositoryRoot)))
	return filepath.Join(base, hex.EncodeToString(sum[:])), nil
}

func digestBytes(content []byte) string {
	sum := sha256.Sum256(content)
	return controlplane.CanonicalDigestPrefix + hex.EncodeToString(sum[:])
}

func readJSON[T any](pathname string) (*T, error) {
	raw, err := os.ReadFile(pathname)
	if errors.Is(err, fs.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	value := new(T)
	if err := json.Unmarshal(raw, value); err != nil {
		return nil, fmt.Errorf("decode %s: %w", pathname, err)
	}
	return value, nil
}

func writeJSON(pathname string, value any) error {
	encoded, err := json.MarshalIndent(value, "", "  ")
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(pathname), 0o700); err != nil {
		return err
	}
	temporary, err := os.CreateTemp(filepath.Dir(pathname), ".tdd-guard-*")
	if err != nil {
		return err
	}
	temporaryPath := temporary.Name()
	if err := errors.Join(temporary.Chmod(0o600), writeAll(temporary, append(encoded, '\n')), temporary.Close()); err != nil {
		_ = os.Remove(temporaryPath)
		return err
	}
	if err := os.Rename(temporaryPath, pathname); err != nil {
		_ = os.Remove(temporaryPath)
		return err
	}
	return nil
}

func writeAll(file *os.File, content []byte) error {
	if _, err := file.Write(content); err != nil {
		return err
	}
	return file.Sync()
}

// state is the loaded per-repository guard state for one invocation.
type state struct {
	repository string
	directory  string
	seal       *Seal
	green      *Green
	diffReview *DiffReview
	archReview *ArchReview
	handoff    *Handoff
}

func loadState(workingDirectory string) (*state, error) {
	repository, err := repositoryRoot(workingDirectory)
	if err != nil {
		return nil, err
	}
	return loadRepositoryState(repository)
}

// loadRepositoryState reads the state of an already-resolved repository. The
// hook resolves repositories from the paths a tool would write, so it never has
// a working directory to hand.
func loadRepositoryState(repository string) (*state, error) {
	directory, err := StateDirectory(repository)
	if err != nil {
		return nil, err
	}
	loaded := &state{repository: repository, directory: directory}
	if loaded.seal, err = readJSON[Seal](filepath.Join(directory, sealFileName)); err != nil {
		return nil, err
	}
	if loaded.green, err = readJSON[Green](filepath.Join(directory, greenFileName)); err != nil {
		return nil, err
	}
	if loaded.diffReview, err = readJSON[DiffReview](filepath.Join(directory, diffReviewFileName)); err != nil {
		return nil, err
	}
	if loaded.archReview, err = readJSON[ArchReview](filepath.Join(directory, archReviewFileName)); err != nil {
		return nil, err
	}
	if loaded.handoff, err = readJSON[Handoff](filepath.Join(directory, handoffFileName)); err != nil {
		return nil, err
	}
	return loaded, nil
}

// sealedTests returns the digests currently in force: the original seal, or the
// most recent recorded amendment when the writer explicitly resealed.
func (s *state) sealedTests() []TestDigest {
	if s.seal == nil {
		return nil
	}
	if count := len(s.seal.Amendments); count > 0 {
		return s.seal.Amendments[count-1].After
	}
	return s.seal.Tests
}

// changedTests reports sealed paths whose current content no longer matches the
// digests in force, including sealed files that were deleted.
func (s *state) changedTests() ([]string, error) {
	changed := make([]string, 0)
	for _, test := range s.sealedTests() {
		content, err := os.ReadFile(filepath.Join(s.repository, filepath.FromSlash(test.Path)))
		if errors.Is(err, fs.ErrNotExist) {
			changed = append(changed, test.Path)
			continue
		}
		if err != nil {
			return nil, err
		}
		if digestBytes(content) != test.Digest {
			changed = append(changed, test.Path)
		}
	}
	return changed, nil
}

// testStat is what a sealed test looked like on disk at one instant. Digest
// catches a change that stayed; modification time and size catch one that was
// undone before anyone looked.
type testStat struct {
	digest  string
	modTime time.Time
	size    int64
}

// sealedTestStats snapshots every sealed test so a later call can tell whether
// any of them moved in between, even transiently.
func (s *state) sealedTestStats() (map[string]testStat, error) {
	stats := make(map[string]testStat, len(s.sealedTests()))
	for _, test := range s.sealedTests() {
		target := filepath.Join(s.repository, filepath.FromSlash(test.Path))
		content, err := os.ReadFile(target)
		if err != nil {
			return nil, err
		}
		info, err := os.Stat(target)
		if err != nil {
			return nil, err
		}
		stats[test.Path] = testStat{digest: digestBytes(content), modTime: info.ModTime(), size: info.Size()}
	}
	return stats, nil
}

// sealedTestsTouchedSince reports sealed tests whose content or metadata differ
// from an earlier snapshot, including tests that no longer exist.
func (s *state) sealedTestsTouchedSince(before map[string]testStat) ([]string, error) {
	after, err := s.sealedTestStats()
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return s.changedTests()
		}
		return nil, err
	}
	touched := make([]string, 0)
	for path, was := range before {
		if now, ok := after[path]; !ok || now != was {
			touched = append(touched, path)
		}
	}
	sort.Strings(touched)
	return touched, nil
}

// records lists the runs tdd-guard performed for this repository, in a stable
// order so two readers of the same state agree byte for byte.
func (s *state) records() []controlplane.GuardRecord {
	collected := make([]controlplane.GuardRecord, 0, 3)
	if s.seal != nil && s.seal.Red.CommandID != "" {
		kind := controlplane.GuardRecordSealRed
		if s.seal.kind() == SealKindBaseline {
			kind = controlplane.GuardRecordSealBaseline
		}
		collected = append(collected, controlplane.GuardRecord{
			Kind: kind, CommandID: s.seal.Red.CommandID, Evidence: s.seal.Red,
		})
	}
	if s.green != nil && s.green.CommandID != "" {
		collected = append(collected, controlplane.GuardRecord{
			Kind: controlplane.GuardRecordGreen, CommandID: s.green.CommandID, Evidence: s.green.CommandEvidence,
		})
	}
	if s.diffReview != nil && s.diffReview.CommandID != "" {
		collected = append(collected, controlplane.GuardRecord{
			Kind: controlplane.GuardRecordDiffReview, CommandID: s.diffReview.CommandID, Evidence: s.diffReview.Command,
		})
	}
	// An unverified arch review (ast-grep absent) records no command, so it never
	// becomes a citeable record: a tool that never ran cannot back a claim.
	if s.archReview != nil && s.archReview.CommandID != "" && s.archReview.Command != nil {
		collected = append(collected, controlplane.GuardRecord{
			Kind: controlplane.GuardRecordArchReview, CommandID: s.archReview.CommandID, Evidence: *s.archReview.Command,
		})
	}
	return collected
}

func (s *state) sealPath() string       { return filepath.Join(s.directory, sealFileName) }
func (s *state) greenPath() string      { return filepath.Join(s.directory, greenFileName) }
func (s *state) diffReviewPath() string { return filepath.Join(s.directory, diffReviewFileName) }
func (s *state) archReviewPath() string { return filepath.Join(s.directory, archReviewFileName) }
func (s *state) handoffPath() string    { return filepath.Join(s.directory, handoffFileName) }

files.guard/hook.go:
package guard

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// Harness names the supported payload and response dialects.
type Harness string

const (
	HarnessClaude      Harness = "claude"
	HarnessCodex       Harness = "codex"
	HarnessAntigravity Harness = "agy"
)

// Event names the supported hook points. Every installed registration passes
// --event: Antigravity payloads carry no event field, and a payload that fails
// to decode carries nothing the guard could classify itself.
const (
	EventPreToolUse   = "PreToolUse"
	EventPostToolUse  = "PostToolUse"
	EventStop         = "Stop"
	EventSubagentStop = "SubagentStop"
)

// EditToolMatchers and ShellToolMatchers are the per-harness tool names the
// installer registers and the guard recognizes.
var (
	EditToolMatchers = map[Harness]string{
		HarnessClaude:      "Edit|Write|MultiEdit|NotebookEdit",
		HarnessCodex:       "apply_patch",
		HarnessAntigravity: "write_to_file|replace_file_content|multi_replace_file_content",
	}
	ShellToolMatchers = map[Harness]string{
		HarnessClaude: "Bash", HarnessCodex: "Bash", HarnessAntigravity: "run_command",
	}
)

// payload is the union of the three harness stdin shapes. Each harness fills
// only its own fields; unknown fields are ignored because hook payloads grow.
type payload struct {
	HookEventName string          `json:"hook_event_name"`
	ToolName      string          `json:"tool_name"`
	ToolInput     json.RawMessage `json:"tool_input"`
	CWD           string          `json:"cwd"`

	SessionID string `json:"session_id"`
	TurnID    string `json:"turn_id"`

	ToolCall *struct {
		Name string          `json:"name"`
		Args json.RawMessage `json:"args"`
	} `json:"toolCall"`
	WorkspacePaths []string `json:"workspacePaths"`
	ConversationID string   `json:"conversationId"`

	TerminationReason string `json:"terminationReason"`
	FullyIdle         bool   `json:"fullyIdle"`
}

// maxPayloadBytes bounds a hook payload. It has to comfortably exceed a whole
// file written by an edit tool: a truncated read is indistinguishable from
// malformed JSON, and treating either as "allow" is the bypass.
const maxPayloadBytes = 64 << 20

func decodePayload(reader io.Reader) (payload, error) {
	var decoded payload
	if reader == nil {
		return decoded, nil
	}
	raw, err := io.ReadAll(io.LimitReader(reader, maxPayloadBytes+1))
	if err != nil {
		return decoded, err
	}
	if len(raw) > maxPayloadBytes {
		return decoded, fmt.Errorf("hook payload exceeds %d bytes", maxPayloadBytes)
	}
	if len(strings.TrimSpace(string(raw))) == 0 {
		return decoded, nil
	}
	if err := json.Unmarshal(raw, &decoded); err != nil {
		return decoded, fmt.Errorf("decode hook payload: %w", err)
	}
	return decoded, nil
}

func (p payload) event(override string) string {
	if override != "" {
		return override
	}
	if p.HookEventName != "" {
		return p.HookEventName
	}
	if p.TerminationReason != "" || p.FullyIdle {
		return EventStop
	}
	return EventPreToolUse
}

func (p payload) tool() string {
	if p.ToolCall != nil {
		return p.ToolCall.Name
	}
	return p.ToolName
}

// session identifies the harness conversation the touch log is keyed on.
// Claude and Antigravity name it directly; Codex documents only a per-turn
// identifier, which still scopes the log more tightly than nothing.
func (p payload) session() string {
	for _, candidate := range []string{p.SessionID, p.ConversationID, p.TurnID} {
		if trimmed := strings.TrimSpace(candidate); trimmed != "" {
			return trimmed
		}
	}
	return ""
}

func (p payload) workingDirectory(fallback string) string {
	if p.CWD != "" {
		return p.CWD
	}
	if len(p.WorkspacePaths) > 0 && p.WorkspacePaths[0] != "" {
		return p.WorkspacePaths[0]
	}
	return fallback
}

// pathKeys are the argument names the three harnesses use for an edit target.
var pathKeys = []string{"file_path", "filePath", "path", "notebook_path", "TargetFile", "target_file", "AbsolutePath", "absolute_path"}

// editTargets extracts every path an edit tool call would write.
func (p payload) editTargets() []string {
	arguments := p.ToolInput
	if p.ToolCall != nil {
		arguments = p.ToolCall.Args
	}
	if len(arguments) == 0 {
		return nil
	}
	var object map[string]json.RawMessage
	if json.Unmarshal(arguments, &object) != nil {
		return nil
	}
	targets := make(map[string]struct{})
	for _, key := range pathKeys {
		var value string
		if raw, ok := object[key]; ok && json.Unmarshal(raw, &value) == nil && value != "" {
			targets[value] = struct{}{}
		}
	}
	// Codex apply_patch carries the whole envelope as one string; its file
	// headers are the only place the touched paths appear.
	for _, key := range []string{"input", "patch"} {
		var envelope string
		if raw, ok := object[key]; ok && json.Unmarshal(raw, &envelope) == nil {
			for _, target := range patchEnvelopePaths(envelope) {
				targets[target] = struct{}{}
			}
		}
	}
	var changes map[string]json.RawMessage
	if raw, ok := object["changes"]; ok && json.Unmarshal(raw, &changes) == nil {
		for target := range changes {
			targets[target] = struct{}{}
		}
	}
	ordered := make([]string, 0, len(targets))
	for target := range targets {
		ordered = append(ordered, target)
	}
	sort.Strings(ordered)
	return ordered
}

func patchEnvelopePaths(envelope string) []string {
	prefixes := []string{"*** Add File: ", "*** Update File: ", "*** Delete File: ", "*** Move to: "}
	paths := make([]string, 0)
	for _, line := range strings.Split(envelope, "\n") {
		for _, prefix := range prefixes {
			if strings.HasPrefix(line, prefix) {
				paths = append(paths, strings.TrimSpace(strings.TrimPrefix(line, prefix)))
			}
		}
	}
	return paths
}

// response is the harness-neutral decision the dialect writers project.
type response struct {
	deny   bool
	notify bool
	reason string
}

func isKnownHookEvent(event string) bool {
	switch event {
	case EventPreToolUse, EventPostToolUse, EventStop, EventSubagentStop:
		return true
	default:
		return false
	}
}

func hasActiveSeal(decoded payload, fallbackDir string) bool {
	workingDirectory := decoded.workingDirectory(fallbackDir)
	cache := newLookups()
	if repository, ok := cache.repositoryForPath(workingDirectory, "."); ok {
		if loaded := cache.load(repository); loaded != nil && loaded.seal != nil {
			return true
		}
	}
	if repository, err := repositoryRoot(workingDirectory); err == nil {
		if loaded := cache.load(repository); loaded != nil && loaded.seal != nil {
			return true
		}
	}
	for _, target := range decoded.editTargets() {
		if repository, ok := cache.repositoryForPath(workingDirectory, target); ok {
			if loaded := cache.load(repository); loaded != nil && loaded.seal != nil {
				return true
			}
		}
	}
	for _, repository := range touchedRepositories(decoded.session()) {
		if loaded := cache.load(repository); loaded != nil && loaded.seal != nil {
			return true
		}
	}
	return false
}

// hook is the single entry point every harness registration calls. It stays
// silent for any repository with no seal so non-fleet sessions are untouched.
func hook(options Options, harnessName Harness, eventOverride string) int {
	decoded, decodeErr := decodePayload(options.Stdin)
	if decodeErr != nil {
		// json.Unmarshal can populate fields before it fails, so nothing that
		// came out of an unreadable payload is trusted -- including the cwd
		// that used to decide, on its own, whether any seal was in force.
		decoded = payload{}
	}
	if !isKnownHookEvent(eventOverride) {
		var configErr string
		if eventOverride == "" {
			configErr = "tdd-guard hook misconfigured: --event is required (must be PreToolUse, PostToolUse, Stop, or SubagentStop)"
		} else {
			configErr = fmt.Sprintf("tdd-guard hook misconfigured: --event %q is not a known event (must be PreToolUse, PostToolUse, Stop, or SubagentStop)", eventOverride)
		}
		sealed := false
		if decodeErr != nil {
			s, err := anySealExists()
			sealed = err == nil && s
		} else {
			sealed = hasActiveSeal(decoded, options.Dir)
		}
		if !sealed {
			fmt.Fprintln(options.Stderr, configErr)
			return 0
		}
		event := decoded.event(eventOverride)
		return emit(options, harnessName, event, response{
			deny:   true,
			reason: configErr,
		})
	}
	event := decoded.event(eventOverride)
	if decodeErr != nil {
		// A seal is in force somewhere and the guard cannot tell what the tool
		// would write, so the only safe answer is refusal.
		sealed, err := anySealExists()
		if err != nil || !sealed {
			return 0
		}
		return emit(options, harnessName, event, response{
			deny:   true,
			reason: "tdd-guard: refusing an unreadable hook payload while a test seal is in force: " + decodeErr.Error(),
		})
	}
	workingDirectory := decoded.workingDirectory(options.Dir)
	var decision response
	switch event {
	case EventPreToolUse:
		decision = preToolUse(harnessName, decoded, workingDirectory)
	case EventPostToolUse:
		decision = postToolUse(harnessName, decoded, workingDirectory)
	case EventStop, EventSubagentStop:
		decision = stopGate(decoded, workingDirectory)
	}
	return emit(options, harnessName, event, decision)
}

// preToolUse judges every path the call would write against the seal of the
// repository that owns that path. The session's own directory decides nothing:
// an absolute path, a traversal, or a symlink reaches a sealed tree from
// anywhere on the filesystem.
func preToolUse(harnessName Harness, decoded payload, workingDirectory string) response {
	if !matchesTool(EditToolMatchers[harnessName], decoded.tool()) {
		return response{}
	}
	cache := newLookups()
	blocked, touched := make([]string, 0), make([]string, 0)
	for _, target := range decoded.editTargets() {
		repository, inRepository := cache.repositoryForPath(workingDirectory, target)
		if !inRepository {
			continue
		}
		loaded := cache.load(repository)
		if loaded == nil || loaded.seal == nil {
			continue
		}
		if !containsString(touched, repository) {
			touched = append(touched, repository)
		}
		if isSealedTestPath(loaded, workingDirectory, target) {
			blocked = append(blocked, filepath.ToSlash(target))
		}
	}
	// The write is about to happen, so the log has to exist before the tool
	// runs; a later shell check or Stop gate is the only thing that reads it.
	_ = recordTouchedRepositories(decoded.session(), touched)
	if len(blocked) == 0 {
		return response{}
	}
	return response{deny: true, reason: "tdd-guard: sealed test paths may not be edited during implementation: " + strings.Join(blocked, ", ") + "; amend them with `tdd-guard reseal --reason <text>` instead"}
}

func postToolUse(harnessName Harness, decoded payload, workingDirectory string) response {
	if !matchesTool(ShellToolMatchers[harnessName], decoded.tool()) {
		return response{}
	}
	resolved := sessionScope(decoded, workingDirectory)
	messages := make([]string, 0, len(resolved.states))
	for _, loaded := range resolved.states {
		changed, err := loaded.changedTests()
		if err != nil || len(changed) == 0 {
			continue
		}
		messages = append(messages, resolved.qualify(loaded, strings.Join(changed, ", ")))
	}
	if len(messages) == 0 {
		return response{}
	}
	return response{notify: true, reason: "tdd-guard: sealed tests changed during implementation: " + strings.Join(messages, "; ") + "; restore them or record `tdd-guard reseal --reason <text>`"}
}

func stopGate(decoded payload, workingDirectory string) response {
	resolved := sessionScope(decoded, workingDirectory)
	blockers := make([]string, 0, 3)
	for _, loaded := range resolved.states {
		found, err := stopGateBlockers(loaded)
		if err != nil {
			continue
		}
		for _, blocker := range found {
			blockers = append(blockers, resolved.qualify(loaded, blocker))
		}
	}
	if len(blockers) > 0 {
		return response{deny: true, reason: "tdd-guard: " + strings.Join(blockers, "; ")}
	}
	if resolved.repository != "" {
		cache := newLookups()
		loaded := cache.load(resolved.repository)
		if loaded == nil || loaded.seal == nil {
			if loaded != nil {
				if _, err := os.Stat(loaded.directory); err == nil {
					if found, err := stopGateBlockers(loaded); err == nil && len(found) > 0 {
						return response{
							deny:   true,
							reason: "tdd-guard: " + strings.Join(found, "; "),
						}
					}
				}
			}
			sourcePaths, err := unsealedSourceChanges(resolved.repository)
			if err == nil && len(sourcePaths) > 0 {
				return response{
					notify: true,
					reason: "tdd-guard: source changed without a TDD seal: " + strings.Join(sourcePaths, ", ") + " — RED->seal->GREEN was skipped",
				}
			}
		}
	}
	return response{}
}

func unsealedSourceChanges(repository string) ([]string, error) {
	changed, err := changedWorkingPaths(repository)
	if err != nil {
		return nil, err
	}
	testPatterns, err := configuredPatterns(repository)
	if err != nil {
		testPatterns = DefaultTestPatterns
	}
	seen := make(map[string]struct{})
	sourcePaths := make([]string, 0)
	for _, relPath := range changed {
		if isSourcePath(relPath, testPatterns) {
			if _, exists := seen[relPath]; !exists {
				seen[relPath] = struct{}{}
				sourcePaths = append(sourcePaths, relPath)
			}
		}
	}
	sort.Strings(sourcePaths)
	return sourcePaths, nil
}

func isSourcePath(relPath string, testPatterns []string) bool {
	relPath = filepath.ToSlash(strings.TrimSpace(relPath))
	if relPath == "" {
		return false
	}
	lower := strings.ToLower(relPath)
	if lower == "docs" || strings.HasPrefix(lower, "docs/") {
		return false
	}
	ext := strings.ToLower(filepath.Ext(relPath))
	switch ext {
	case ".md", ".json", ".toml", ".yaml", ".yml":
		return false
	}
	for _, pattern := range testPatterns {
		if matchTestPattern(pattern, relPath) {
			return false
		}
	}
	return true
}

func containsString(values []string, candidate string) bool {
	for _, value := range values {
		if value == candidate {
			return true
		}
	}
	return false
}

func matchesTool(matcher, tool string) bool {
	if tool == "" {
		return false
	}
	for _, candidate := range strings.Split(matcher, "|") {
		if candidate == tool {
			return true
		}
	}
	return false
}

// emit projects one decision into the harness's documented dialect.
//
// PostToolUse cannot block anywhere, so its message goes to stderr. Claude and
// Codex document exit 2 as that channel; Antigravity does not, so its message
// exits 0 rather than claiming a blocking semantic. A `permissionDecision` on
// PostToolUse or Stop is read by nobody, which is why the event has to be known
// from the registration rather than inferred from a payload that may not have
// decoded at all.
func emit(options Options, harnessName Harness, event string, decision response) int {
	if !decision.deny && !decision.notify {
		return 0
	}
	if decision.notify {
		// notify is visible-but-non-blocking. At PostToolUse exit 2 shows the
		// message without blocking (the tool already ran); at Stop exit 2 would
		// BLOCK, so surface it through a non-blocking channel instead.
		if event == EventPostToolUse {
			fmt.Fprintln(options.Stderr, decision.reason)
			if harnessName == HarnessAntigravity {
				return 0
			}
			return 2
		}
		if harnessName == HarnessAntigravity {
			fmt.Fprintln(options.Stderr, decision.reason)
			return 0
		} else {
			writeJSONLine(options, map[string]any{"systemMessage": decision.reason})
		}
		return 0
	}
	if decision.deny && event == EventPostToolUse && harnessName != HarnessAntigravity {
		fmt.Fprintln(options.Stderr, decision.reason)
		return 2
	}
	switch {
	case harnessName == HarnessClaude && (event == EventStop || event == EventSubagentStop):
		fmt.Fprintln(options.Stderr, decision.reason)
		return 2
	case harnessName == HarnessClaude:
		writeJSONLine(options, map[string]any{"hookSpecificOutput": map[string]any{
			"hookEventName": event, "permissionDecision": "deny", "permissionDecisionReason": decision.reason,
		}})
	case harnessName == HarnessCodex && (event == EventStop || event == EventSubagentStop):
		writeJSONLine(options, map[string]any{"continue": false, "reason": decision.reason})
	case harnessName == HarnessCodex:
		writeJSONLine(options, map[string]any{"decision": "block", "reason": decision.reason})
	case event == EventStop || event == EventSubagentStop:
		writeJSONLine(options, map[string]any{"decision": "continue", "reason": decision.reason})
	default:
		writeJSONLine(options, map[string]any{"decision": "deny", "reason": decision.reason})
	}
	return 0
}

func writeJSONLine(options Options, value any) {
	encoded, err := json.Marshal(value)
	if err != nil {
		return
	}
	fmt.Fprintln(options.Stdout, string(encoded))
}

files.guard/run.go:
package guard

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"
)

const usageCommands = `<command> [options]

  seal --tests <globs|paths> (--red-command <argv...> | --green-baseline <argv...>)
  verify --green-command <argv...> [--coverage-command <argv...>] [--min-coverage <float>]
  reseal --reason <text>
  diff-review record --findings <file>
  arch-check --assertions <file>
  hook --harness claude|codex|agy --event PreToolUse|PostToolUse|Stop|SubagentStop
  status [--json]
  version`

func usage() string {
	return "usage: " + filepath.Base(os.Args[0]) + " " + usageCommands
}

// Options carries the process boundary so every command is directly testable.
type Options struct {
	Dir    string
	Stdin  io.Reader
	Stdout io.Writer
	Stderr io.Writer
}

// Run executes one subcommand and returns the process exit code. Code 2 is the
// harness message and refusal channel; 1 is an operational failure.
func Run(options Options, args []string) int {
	if options.Stdout == nil {
		options.Stdout = io.Discard
	}
	if options.Stderr == nil {
		options.Stderr = io.Discard
	}
	if options.Dir == "" {
		options.Dir, _ = os.Getwd()
	}
	if len(args) == 0 {
		fmt.Fprintln(options.Stderr, usage())
		return 1
	}
	if len(args) == 1 && (args[0] == "--help" || args[0] == "-h") {
		fmt.Fprintln(options.Stdout, usage())
		return 0
	}
	// Answered before dispatch, and so before any loadState: an installed guard
	// usually runs from $HOME, and must still report its version there.
	if len(args) == 1 && (args[0] == "version" || args[0] == "--version" || args[0] == "-v") {
		fmt.Fprintln(options.Stdout, "tdd-guard "+VersionString())
		return 0
	}
	code, err := dispatch(options, args)
	if err != nil {
		fmt.Fprintln(options.Stderr, "tdd-guard:", err)
		return 1
	}
	return code
}

func dispatch(options Options, args []string) (int, error) {
	command, rest := args[0], args[1:]
	if command == "hook" {
		flags, err := parseFlags(rest, map[string]bool{"--harness": true, "--event": true})
		if err != nil {
			return 1, err
		}
		harnessName := Harness(flags.values["--harness"])
		switch harnessName {
		case HarnessClaude, HarnessCodex, HarnessAntigravity:
		default:
			return 1, fmt.Errorf("hook requires --harness claude|codex|agy")
		}
		return hook(options, harnessName, flags.values["--event"]), nil
	}

	if command == "seal" {
		flags, err := parseFlags(rest, map[string]bool{"--tests": true, "--red-command": false, "--green-baseline": false})
		if err != nil {
			return 1, err
		}
		loaded, err := loadState(options.Dir)
		if err != nil {
			return 1, err
		}
		return 0, seal(loaded, flags.lists["--tests"], flags.argv["--red-command"], flags.argv["--green-baseline"])
	}

	loaded, err := loadState(options.Dir)
	if err != nil {
		return 1, err
	}
	switch command {
	case "verify":
		flags, err := parseFlags(rest, map[string]bool{"--green-command": false, "--coverage-command": false, "--min-coverage": true})
		if err != nil {
			return 1, err
		}
		minCoverage := 0.0
		if raw, ok := flags.values["--min-coverage"]; ok {
			minCoverage, err = strconv.ParseFloat(raw, 64)
			if err != nil {
				return 1, fmt.Errorf("--min-coverage %q is not a number: %w", raw, err)
			}
		}
		return 0, verify(loaded, flags.argv["--green-command"], flags.argv["--coverage-command"], minCoverage, options.Stderr)
	case "reseal":
		flags, err := parseFlags(rest, map[string]bool{"--reason": true})
		if err != nil {
			return 1, err
		}
		return 0, reseal(loaded, flags.values["--reason"])
	case "diff-review":
		if len(rest) == 0 || rest[0] != "record" {
			return 1, fmt.Errorf("usage: tdd-guard diff-review record --findings <file>")
		}
		flags, err := parseFlags(rest[1:], map[string]bool{"--findings": true})
		if err != nil {
			return 1, err
		}
		return 0, recordDiffReview(loaded, flags.values["--findings"])
	case "handoff":
		flags, err := parseFlags(rest, map[string]bool{"--to": true})
		if err != nil {
			return 1, err
		}
		return 0, handoff(loaded, flags.values["--to"])
	case "arch-check":
		flags, err := parseFlags(rest, map[string]bool{"--assertions": true})
		if err != nil {
			return 1, err
		}
		return archCheck(loaded, flags.values["--assertions"], options.Stderr)
	case "status":
		// Output is machine-readable either way; --json is accepted so callers
		// can name the contract they depend on.
		if len(rest) > 1 || (len(rest) == 1 && rest[0] != "--json") {
			return 1, fmt.Errorf("status takes no arguments beyond --json, got %q", strings.Join(rest, " "))
		}
		report, err := status(loaded)
		if err != nil {
			return 1, err
		}
		encoded, err := json.Marshal(report)
		if err != nil {
			return 1, err
		}
		fmt.Fprintln(options.Stdout, string(encoded))
		return 0, nil
	default:
		fmt.Fprintln(options.Stderr, usage())
		return 1, fmt.Errorf("unknown command %q", command)
	}
}

// parsedFlags separates single-value flags, repeatable whitespace-separated
// lists, and trailing argv arrays. Trailing argv is never re-split or passed
// through a shell.
type parsedFlags struct {
	values map[string]string
	lists  map[string][]string
	argv   map[string][]string
}

// parseFlags reads `--flag value` pairs; a flag declared as non-scalar consumes
// the arguments up to the next known flag as one argv array. Stopping at the
// next known flag rather than at the end is what lets two argv arrays coexist,
// e.g. `verify --green-command <argv...> --coverage-command <argv...>`.
func parseFlags(args []string, scalar map[string]bool) (parsedFlags, error) {
	parsed := parsedFlags{values: map[string]string{}, lists: map[string][]string{}, argv: map[string][]string{}}
	for index := 0; index < len(args); index++ {
		name := args[index]
		isScalar, known := scalar[name]
		if !known {
			return parsed, fmt.Errorf("unexpected argument %q", name)
		}
		if !isScalar {
			end := index + 1
			for end < len(args) {
				if _, isFlag := scalar[args[end]]; isFlag {
					break
				}
				end++
			}
			if end == index+1 {
				return parsed, fmt.Errorf("%s requires an argv array", name)
			}
			parsed.argv[name] = args[index+1 : end]
			index = end - 1
			continue
		}
		if index+1 >= len(args) {
			return parsed, fmt.Errorf("%s requires a value", name)
		}
		value := args[index+1]
		parsed.values[name] = value
		parsed.lists[name] = append(parsed.lists[name], strings.Fields(value)...)
		index++
	}
	return parsed, nil
}

func isAfter(later, earlier string) bool {
	left, leftErr := time.Parse(time.RFC3339Nano, later)
	right, rightErr := time.Parse(time.RFC3339Nano, earlier)
	if leftErr != nil || rightErr != nil {
		return false
	}
	return !left.Before(right)
}

